#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
"""Synthetic task-chain generator: a seeded logical callback graph (family + size) with data patterns, compute profiles
and a deployment -> descriptor JSON (the ground truth; schema in descriptor_schema.json).
  python3 synth_gen.py --family chain|tree|star|bipartite|layered|er|ba|cycle|zoo --n 12 --seed 1 [--nodes-per-process 3]
                       [--lang rclcpp|rclpy|mix] [--intra on|off|mix] [--executor single|multi|mix] [--gpu] -o descriptor.json
Legality (enforced): every weakly connected component has a timer source; a cycle is broken by a timer reader
(sampled read, no message storm); fan-in callbacks are joins with an explicit consumption pattern; total busy demand
stays below the CPU budget; processes <= --max-processes."""
import sys, argparse, json, math, random, sys
PATTERN_JOIN = ['queue_batch_clear', 'map_keyed_timeout', 'mf_exact', 'mf_approx', 'ptr_hold']
PATTERN_SAMPLED = ['field_overwrite', 'copy', 'ptr_hold', 'deque_sliding_pop']
MSG = ['small', 'medium', 'pointcloud']
def busy_profile(rng, scale):
    k = rng.choice(['const', 'uniform', 'bimodal', 'heavy'])
    base = rng.choice([200, 500, 1000, 2000, 5000]) * scale
    return dict(kind=k, busy_us=base, spread=0.3 if k != 'const' else 0.0)
def gen_edges(rng, fam, n):
    """directed callback graph as edge list; returns (sources, edges)"""
    E = []
    if fam == 'chain':
        E = [(i, i + 1) for i in range(n - 1)]
    elif fam == 'tree':
        E = [(rng.randrange(0, i), i) for i in range(1, n)]
    elif fam == 'star':
        E = [(0, i) for i in range(1, n)]
    elif fam == 'bipartite':          # k sources fan into one join, which fans out to the rest
        k = max(2, n // 3); E = [(i, k) for i in range(k)] + [(k, j) for j in range(k + 1, n)]
    elif fam == 'layered':
        L = max(2, int(math.sqrt(n))); layers = [list(range(i, n, L)) for i in range(L)]
        for a, b in zip(layers, layers[1:]):
            for v in b:
                for u in rng.sample(a, min(len(a), rng.choice([1, 1, 2]))): E.append((u, v))
    elif fam == 'er':
        p = min(1.0, 2.0 / max(1, n - 1))
        for u in range(n):
            for v in range(u + 1, n):
                if rng.random() < p: E.append((u, v))
    elif fam == 'ba':
        deg = [1, 1]; E = [(0, 1)]
        for v in range(2, n):
            for u in set(rng.choices(range(v), weights=deg[:v], k=rng.choice([1, 2]))): E.append((u, v)); deg[u] += 1
            deg.append(1)
    elif fam == 'cycle':
        E = [(i, (i + 1) % n) for i in range(n)]
    elif fam == 'zoo':                # one of everything: chain, 3-way join, timer reader, cycle, fan-out
        E = [(0, 1), (1, 2), (0, 3), (3, 4), (2, 5), (4, 5), (6, 5), (5, 7), (7, 8), (8, 7), (5, 9), (5, 10)]
        n = max(n, 11)
    else:
        raise SystemExit(f'unknown family {fam}')
    return n, sorted(set(E))
def main():
    ap = argparse.ArgumentParser(); ap.add_argument('--family', required=True); ap.add_argument('--n', type=int, default=12); ap.add_argument('--seed', type=int, default=1)
    ap.add_argument('--nodes-per-process', type=int, default=3); ap.add_argument('--callbacks-per-node', type=int, default=2)
    ap.add_argument('--lang', default='rclcpp'); ap.add_argument('--intra', default='mix'); ap.add_argument('--executor', default='mix')
    ap.add_argument('--gpu', action='store_true'); ap.add_argument('--max-processes', type=int, default=200); ap.add_argument('--cpu-budget', type=float, default=8.0)
    ap.add_argument('--duration', type=float, default=60.0); ap.add_argument('-o', '--out', required=True)
    a = ap.parse_args(); rng = random.Random(a.seed)
    n, E = gen_edges(rng, a.family, a.n)
    preds = {v: [u for u, w in E if w == v] for v in range(n)}; succs = {u: [w for x, w in E if x == u] for u in range(n)}
    # roles: no predecessor -> timer source; in a cycle every vertex has a predecessor -> break it with a timer reader
    roles = {}
    comp = {}; cid = 0
    for v in range(n):
        if v in comp: continue
        stack = [v]; comp[v] = cid
        while stack:
            x = stack.pop()
            for y in preds[x] + succs[x]:
                if y not in comp: comp[y] = cid; stack.append(y)
        cid += 1
    # LEGALITY: every DIRECTED cycle must contain a timer reader (sampled read). A join inside a cycle deadlocks
    # (it waits for an input that only its own output produces: zoo_s1 cb_007<->cb_008 never fired) and a plain
    # subscription cycle is a message storm. Repeat: find a non-trivial SCC among the non-timer-reader vertices,
    # turn its highest in-degree member into a timer reader, until the remaining graph is acyclic.
    def sccs(vertices):
        index = {}; low = {}; on = set(); st = []; out = []; counter = [0]
        sys.setrecursionlimit(max(10000, 4 * n))
        def strong(v):
            index[v] = low[v] = counter[0]; counter[0] += 1; st.append(v); on.add(v)
            for w in succs[v]:
                if w not in vertices: continue
                if w not in index: strong(w); low[v] = min(low[v], low[w])
                elif w in on: low[v] = min(low[v], index[w])
            if low[v] == index[v]:
                comp_ = []
                while True:
                    w = st.pop(); on.discard(w); comp_.append(w)
                    if w == v: break
                out.append(comp_)
        for v in vertices:
            if v not in index: strong(v)
        return out
    while True:
        live = {v for v in range(n) if roles.get(v) != 'timer_reader'}
        cyc = [c_ for c_ in sccs(live) if len(c_) > 1 or any(w == c_[0] for w in succs[c_[0]])]
        if not cyc: break
        c_ = cyc[0]
        roles[max(c_, key=lambda v: (len(preds[v]), -v))] = 'timer_reader'
    for v in range(n):
        if v in roles: continue
        if not preds[v]: roles[v] = 'timer_source'
        elif len(preds[v]) >= 2: roles[v] = 'join'
        elif not succs[v] and rng.random() < 0.5: roles[v] = 'sink'
        else: roles[v] = 'subscription'
    # a few single-input readers become timer readers (sampled), to exercise that mechanism
    for v in range(n):
        if roles[v] == 'subscription' and succs[v] and rng.random() < 0.15: roles[v] = 'timer_reader'
    # deployment: callbacks -> nodes -> processes; executors, intra, language
    node_of = {v: f'node_{v // a.callbacks_per_node:03d}' for v in range(n)}
    nodes = sorted(set(node_of.values()))
    proc_of = {nd: f'proc_{i // a.nodes_per_process:03d}' for i, nd in enumerate(nodes)}
    if len(set(proc_of.values())) > a.max_processes: raise SystemExit('too many processes for the cap')
    def pick(opt, choices): return rng.choice(choices) if opt == 'mix' else opt
    dep_nodes = {}
    for nd in nodes:
        ex = pick(a.executor, ['single', 'multi']); lang = pick(a.lang, ['rclcpp', 'rclcpp', 'rclpy'])
        dep_nodes[nd] = dict(process=proc_of[nd], container=('component_container_mt' if ex == 'multi' else 'component_container') if lang == 'rclcpp' else 'none',
                             executor=ex, threads=(4 if ex == 'multi' else 1), intra_process=(pick(a.intra, ['on', 'off']) == 'on') if lang == 'rclcpp' else False, language=lang, priority=0)
    # callbacks + edges with mechanisms and expected FISH classification
    cbs = []; edges = []; topic_of = {v: f'/synth/t{v:03d}' for v in range(n)}
    scale = 1.0
    for v in range(n):
        r = roles[v]; nd = node_of[v]; lang = dep_nodes[nd]['language']
        cb = dict(id=f'cb_{v:03d}', role=r, node=nd, language=lang, topics_out=[topic_of[v]] if (succs[v] or r != 'sink') else [],
                  msg_type=rng.choice(MSG) if lang == 'rclcpp' else 'small', compute=busy_profile(rng, scale), callback_group='default')
        if r == 'timer_source': cb['period_ms'] = rng.choice([10, 20, 50, 100, 200])
        if r == 'timer_reader': cb['period_ms'] = rng.choice([20, 50, 100]); cb['data_pattern'] = rng.choice(['field_overwrite', 'ptr_hold', 'deque_sliding_pop']); cb['consumes'] = [f'cb_{u:03d}' for u in preds[v]]
        if r in ('subscription', 'sink'): cb['topic_in'] = topic_of[preds[v][0]]; cb['data_pattern'] = 'none'
        if r == 'join':
            cb['topics_in'] = [topic_of[u] for u in preds[v]]; cb['data_pattern'] = rng.choice(PATTERN_JOIN if lang == 'rclcpp' else ['queue_batch_clear', 'field_overwrite'])
            cb['consumes'] = [f'cb_{u:03d}' for u in preds[v]]
        if a.gpu and lang == 'rclcpp' and rng.random() < 0.3:
            cb['compute']['cuda'] = dict(kernel_us=rng.choice([200, 1000, 5000]), memcpy_bytes=rng.choice([0, 65536, 1 << 20]), stream=rng.choice(['per_cb', 'shared']), sync=rng.random() < 0.7)
        cbs.append(cb)
    for u, v in E:
        same_proc = proc_of[node_of[u]] == proc_of[node_of[v]]
        intra = same_proc and dep_nodes[node_of[u]]['intra_process'] and dep_nodes[node_of[v]]['intra_process'] and dep_nodes[node_of[u]]['language'] == 'rclcpp'
        r = roles[v]
        if r == 'timer_reader':
            # the message arrives on a subscription of the same node and is deposited; the timer reads it
            mech = {'field_overwrite': 'member_field', 'ptr_hold': 'ptr_hold', 'deque_sliding_pop': 'member_deque'}[cbs[v]['data_pattern']]
            edges.append(dict(**{'from': f'cb_{u:03d}', 'to': f'cb_{v:03d}'}, mechanism='topic_intra' if intra else 'topic_dds', topic=topic_of[u], expected='trigger', via_deposit=True))
            edges.append(dict(**{'from': f'cb_{u:03d}_deposit', 'to': f'cb_{v:03d}'}, mechanism=mech, expected='sampled'))
        elif r == 'join':
            mech = {'queue_batch_clear': 'member_queue', 'map_keyed_timeout': 'member_map', 'mf_exact': 'mf_sync', 'mf_approx': 'mf_sync', 'ptr_hold': 'ptr_hold', 'field_overwrite': 'member_field'}[cbs[v]['data_pattern']]
            edges.append(dict(**{'from': f'cb_{u:03d}', 'to': f'cb_{v:03d}'}, mechanism='topic_intra' if intra else 'topic_dds', topic=topic_of[u], expected='trigger'))
            edges.append(dict(**{'from': f'cb_{u:03d}', 'to': f'cb_{v:03d}'}, mechanism=mech, expected='join' if mech != 'member_field' else 'sampled'))
        else:
            edges.append(dict(**{'from': f'cb_{u:03d}', 'to': f'cb_{v:03d}'}, mechanism='topic_intra' if intra else 'topic_dds', topic=topic_of[u], expected='trigger'))
    # cpu budget: sources' rates propagate; crude estimate = sum(busy_us * rate)
    rate = {v: (1000.0 / cbs[v]['period_ms']) if 'period_ms' in cbs[v] else None for v in range(n)}
    for _ in range(n):
        for v in range(n):
            if rate[v] is None and preds[v] and all(rate[u] is not None for u in preds[v]): rate[v] = max(rate[u] for u in preds[v])
    demand = sum((rate[v] or 0) * cbs[v]['compute']['busy_us'] / 1e6 for v in range(n))
    if demand > a.cpu_budget:
        f = a.cpu_budget / demand * 0.8
