    desc = dict(name=f'synth_{a.family}_n{n}_s{a.seed}', seed=a.seed, family=a.family, callbacks=cbs, edges=edges,
                deployment=dict(nodes=dep_nodes, use_sim_time=False, duration_s=a.duration),
                legality=dict(components=cid, sources=sum(1 for r in roles.values() if r == 'timer_source'), cycles_broken=sum(1 for r in roles.values() if r == 'timer_reader'),
                              processes=len(set(proc_of.values())), cpu_demand_cores=round(min(demand, a.cpu_budget), 2)))
    json.dump(desc, open(a.out, 'w'), indent=1)
